import json
from pathlib import Path
p=Path('/workspace/sites/olympiad-atlas');new=[]
def add(y,n,r,t,tags,s,reason,sol=None,note=''):
 u=f'https://cms.math.ca/wp-content/uploads/2019/07/sol{y}.pdf';q=f'https://cms.math.ca/wp-content/uploads/2019/07/exam{y}.pdf'
 new.append(dict(id=f'ca-cmo-{y}-{n}',country='Canada',competition='CMO',year=y,number=str(n),statement=s,solution=sol or f'[View official worked solution PDF]({u}). See Problem {n}.',sourceUrl=q,solutionUrl=u,solutionKind='original-exposition' if sol else 'source-link',topic=t,tags=tags.split('|'),difficulty=r,ratingReason=reason,reviewStatus='individually-assessed',notes='Primary Canadian Mathematical Society paper and worked solutions read. Mathematical statement restated. '+note))
add(2010,1,7,'Combinatorics','Tilings|Binary representation|Induction|Extremal principle',r'An $n$-staircase consists of left-aligned rows of unit squares of lengths $1,2,\ldots,n$. Let $f(n)$ be the smallest number of squares of positive integer side length needed to tile it. Determine all $n$ for which (a) $f(n)=n$; (b) $f(n)=n+1$.','The n boundary cells give the lower bound, but equality forces a recursive sequence of square sizes. The n+1 case requires locating the unique tile missing that boundary and analyzing overlapping smaller staircases; this leads to binary expansions with exactly one zero.')
add(2010,2,4.5,'Geometry','Tangent-chord theorem|Similarity|Circumradius',r'Points $A,B,P$ lie on a circle. Let $a,b$ be the perpendicular distances from $P$ to the tangent lines at $A,B$, respectively, and let $c$ be the perpendicular distance from $P$ to line $AB$. Prove that $c^2=ab$.','The useful relations are PA²=2Ra, PB²=2Rb and c=PA·PB/(2R). Finding them through right-triangle similarity or tangent-chord angles reduces the identity to a short multiplication.')
add(2010,3,5,'Number theory','Relative speed|Coprimality|Euler totient|Counting',r'Three skaters start together on an oval and move in the same direction at constant speeds $1,L,3.14$ laps per minute, where $1<L<3.14$. They stop the first time all three meet again, possibly away from their starting point. How many values of $L$ give exactly $117$ pairwise overtakes before that meeting? Overtakes at the initial and final meetings are not counted.','In the slow skater’s frame, the first common meeting corresponds to two coprime integer lap counts. The three pairwise passing counts sum to 2n−3, fixing n=60; the remaining count is φ(60).',r'The answer is $16$. Work in the frame of the slowest skater. At the first common meeting let the fastest and middle skaters have completed $n$ and $m$ relative laps. Then $0<m<n$, and $\gcd(m,n)=1$, since otherwise all three would have met earlier. Conversely every such coprime pair determines $L=1+2.14m/n$ and a first common meeting.\n\nThe fastest overtakes the slowest $n-1$ times, the middle overtakes the slowest $m-1$ times, and the fastest overtakes the middle $n-m-1$ times. Their sum is $2n-3=117$, giving $n=60$. Thus the number of choices is $\varphi(60)=60(1-1/2)(1-1/3)(1-1/5)=\boxed{16}$.'.replace('\\n','\n'))
add(2010,4,7,'Combinatorics','Graph colouring|Parity|Induction|Linear algebra',r'All vertices of a finite simple undirected graph are initially black. A move chooses one vertex and reverses the colour of that vertex and all its neighbours. Must there always be a finite sequence of moves that makes every vertex white? Prove your answer.','A successful induction must tolerate an exceptional vertex. Combining the resulting moves works immediately when the vertex count is even; for odd order the degree-parity lemma supplies a carefully chosen additional move. The ability to compose toggles modulo 2 is central.')
add(2010,5,6.5,'Algebra','Integer polynomials|Polynomial division|Congruences|Asymptotics',r'Let $P,Q$ be polynomials with integer coefficients and put $a_n=n!+n$. Suppose $P(a_n)/Q(a_n)$ is an integer for every positive integer $n$. Prove that $P(m)/Q(m)$ is an integer for every integer $m$ for which $Q(m)\ne0$.','First polynomial division and the fixed denominator of the quotient force the remainder to vanish by a small-error argument. Then factorials let the testing sequence represent every residue class modulo that denominator; both stages are needed.')
add(2011,1,4,'Number theory','Digit sums|Congruences|Size bounds',r'A 70-digit positive integer is called admissible if each digit $1,2,\ldots,7$ occurs exactly ten times, with no other digits. Prove that no admissible integer divides a distinct admissible integer.','Equal digit sums force the difference to be divisible by 9, while each admissible number is coprime to 3. A hypothetical proper multiple would then be at least ten times as large, contradicting the digit-length bounds.')
add(2011,2,5.5,'Geometry','Angle bisectors|Cyclic quadrilateral|Similarity|Parallel lines',r'Let $ABCD$ be cyclic, with neither pair of opposite sides parallel. Put $X=AB\cap CD$ and $Y=AD\cap BC$. The angle bisector of $\angle AXD$ meets $AD,BC$ at $E,F$, and the angle bisector of $\angle AYB$ meets $AB,CD$ at $G,H$. Prove that $EGFH$ is a parallelogram.','Two similarities from the original cyclic quadrilateral identify four ratios with the same diagonal ratio. Applying the angle-bisector theorem twice then proves that opposite sides of EGFH are parallel to the original diagonals.')
add(2011,3,5.5,'Algebra','Geometric inequalities|Cauchy-Schwarz|Projection|Area',r'A square is partitioned into finitely many axis-aligned rectangles, each coloured red or white. In each white rectangle write width divided by height; in each red rectangle write height divided by width. If the total red area equals the total white area, determine the minimum possible sum of all the written numbers.','The essential geometric observation is a projection dichotomy: either the white widths or the red heights cover a full side length. Cauchy–Schwarz then bounds one colour’s contribution by 2 and the area condition bounds the other by 1/2, with a sharp two-rectangle construction.')
add(2011,5,6.5,'Number theory','Signed sums|Finite differences|Congruences|Construction',r'Fix a positive integer $d$. Prove that every integer $S$ can be written as $\displaystyle S=\sum_{k=1}^n\varepsilon_k(1+kd)^2$ for some positive integer $n$ and signs $\varepsilon_k\in\{-1,1\}$.','Four-term signed blocks have constant value ±4d², so they can adjust any constructed sum within its residue class. The remaining challenge is to obtain every residue class modulo 4d² by controlling parity and flipping selected signs in a long initial block.')
add(2012,2,6,'Number theory','Least common multiple|Prime valuations|Construction',r'For positive integers $n,k$, let $L(n,k)=\operatorname{lcm}(n,n+1,\ldots,n+k-1)$. Prove that for every integer $b$ there exist positive integers $n,k$ for which $L(n,k)>bL(n+1,k)$.','The shift changes only two endpoints. Choosing a prime cube as the removed endpoint and a prime-square interval isolates a large change in one prime valuation while controlling every other factor.',r'''Choose a prime $p>\max(b,2)$ and let $n=p^3$, $k=p^2$. Write
$$M=\operatorname{lcm}(p^3+1,p^3+2,\ldots,p^3+p^2-1).$$
No member of this interval is divisible by $p^2$, while $p^3+p$ is divisible by $p$. Thus the exact power of $p$ dividing $M$ is $p^1$, and adjoining $p^3$ multiplies the least common multiple by $p^2$:
$$L(p^3,p^2)=p^2M.$$
The new endpoint after shifting is $p^3+p^2=p^2(p+1)$. The interval defining $M$ has $p^2-1\ge p+1$ consecutive integers and therefore contains a multiple of $p+1$; hence $p+1\mid M$. Adjoining the new endpoint consequently multiplies $M$ by exactly $p$:
$$L(p^3+1,p^2)=pM.$$
The ratio is $p>b$, as required.''')
add(2012,3,5.5,'Geometry','Excentres|Angle-bisector concurrency|Tangent lengths',r'In a convex quadrilateral $ABCD$, the diagonals meet at $P$ and $AC+AD=BC+BD$. Prove that the internal bisectors of $\angle ACB$, $\angle ADB$, and $\angle APB$ are concurrent.','Interpret the two intersections with the bisector at P as excentres of triangles PBC and PAD. The given side-sum identity says their tangent lengths from P coincide, forcing the two excircles, and hence their centres, to coincide.')
add(2012,4,6.5,'Combinatorics','Algorithms|Grid movement|Invariants|Shortest paths',r'Robots occupy cells of a finite rectangular grid; several may share a cell. Each cell edge is passable or impassable, and all boundary edges are impassable. A command up, down, left, or right makes every robot cross the edge in that direction if it is passable, and otherwise stay still. Suppose that any individual robot can be moved to any cell by a finite command sequence. Prove that one command sequence can make all the robots occupy the same cell.','It suffices to merge two robots repeatedly. Choose a shortest route from one to the other: either a blocked move decreases the shortest-path distance, or both translate by the same nonzero vector. Repeating the route cannot keep translating inside a finite grid.')
add(2012,5,7,'Combinatorics','Termination|Recurrences|Induction|Sharp bounds',r'A shelf contains books labelled $1,2,\ldots,n$ in some order. A move chooses a book labelled $k$ that lies to the right of position $k$, removes it, and reinserts it in position $k$, shifting intervening books one place right. (a) Prove that every sequence of such moves eventually sorts the shelf. (b) Determine the maximum possible number of moves.','Bounding how often book k can be moved gives an exponential recurrence controlled by smaller labels. The sharp value 2^(n−1)−1 requires a recursively constructed worst-case move sequence, not merely a termination invariant.')
add(2013,1,4,'Algebra','Polynomials|Degree comparison|Functional identities',r'Find all real-coefficient polynomials $P$ for which $(x+1)P(x-1)-(x-1)P(x)$ is constant.','Although the leading terms cancel, the next coefficient is (2−n) times the leading coefficient of P. This forces any nonconstant solution to be quadratic; substituting then gives P(x)=ax²+ax+c.')
add(2013,2,5,'Combinatorics','Permutations|Modular arithmetic|Construction',r'For which positive integers $n$ is there a permutation $a_1,\ldots,a_n$ of $1,\ldots,n$ such that $0,a_1,a_1+a_2,\ldots,a_1+\cdots+a_n$ have pairwise distinct residues modulo $n+1$?','The total sum rules out even n immediately. For odd n, interleaving ascending odd terms with descending even terms makes successive partial sums alternate through the positive and negative residues, giving the required construction.')
add(2013,3,5,'Geometry','Centroid|Right triangles|Power of a point|Similarity',r'Let $G$ be the centroid of a right triangle $ABC$ with $\angle C=90^\circ$. Choose $P$ on ray $AG$ with $\angle CPA=\angle CAB$, and $Q$ on ray $BG$ with $\angle CQB=\angle ABC$. Prove that the circles $(AQG)$ and $(BPG)$ have a common point on side $AB$.','The common point is the altitude foot from C. The midpoint of the hypotenuse identifies a useful isosceles triangle, producing AG·AP=AC²; the usual right-triangle projection identity then gives the cyclicity by power of a point.')
add(2013,4,6.5,'Combinatorics','Lattice geometry|Ceiling function|Inequalities|Double counting',r'Fix a positive integer $n$. For each positive integer $j$ and real $r>0$, define $f_j(r)=\min(jr,n)+\min(j/r,n)$ and $g_j(r)=\min(\lceil jr\rceil,n)+\min(\lceil j/r\rceil,n)$. Prove $\displaystyle\sum_{j=1}^nf_j(r)\le n^2+n\le\sum_{j=1}^ng_j(r)$.','The two reciprocal slopes represent complementary parts of a square. Rectangle-area errors prove one inequality; counting cells intersected by a line proves the other. Building this shared geometric interpretation is more demanding than routine ceiling estimates.')
add(2013,5,7,'Geometry','Circle tangency|Reflection|Auxiliary circles|Directed angles',r'Let $O$ be the circumcentre of an acute triangle $ABC$. A circle $\Gamma$ through $A$ meets segments $AB,AC$ again at $P,Q$ such that $\angle BOP=\angle ABC$ and $\angle COQ=\angle ACB$. Prove that the reflection of line $BC$ in line $PQ$ is tangent to $\Gamma$.','A substantial auxiliary construction is needed: intersect circle BOP with BC again at R, then establish both APOQ and CQOR as cyclic. The resulting angle relations identify circle PQR as the reflected circle and prove its tangency to BC.')
add(2014,1,4.5,'Algebra','Telescoping sums|AM-GM|Product constraint',r'Positive real numbers $a_1,\ldots,a_n$ have product $1$. Prove that $\displaystyle\sum_{j=1}^n\frac{a_j}{\prod_{i=1}^j(1+a_i)}\ge\frac{2^n-1}{2^n}$.','Recognize each summand as the difference of two reciprocal partial products. The resulting telescoping expression reduces the inequality to ∏(1+a_i)≥2^n, proved by AM–GM.',r'''Put $B_0=1$ and $B_j=\prod_{i=1}^j(1+a_i)$. Then
$$\frac{a_j}{B_j}=\frac1{B_{j-1}}-\frac1{B_j}.$$
The whole sum is $1-1/B_n$. Since $1+a_i\ge2\sqrt{a_i}$, multiplication gives $B_n\ge2^n\sqrt{a_1\cdots a_n}=2^n$. Thus the sum is at least $1-2^{-n}$, with equality when every $a_i=1$.''','The official proof’s B₀=0 is an evident typo; the original exposition uses B₀=1.')
add(2014,2,5,'Combinatorics','Majorities|Double counting|Colouring|Sharp construction',r'Let $m,n$ be odd positive integers. Colour an $m\times n$ board red or blue. Count the rows containing more red than blue cells, and the columns containing more blue than red cells. Determine the greatest possible sum of these two counts.','Counting colour totals rules out both m+n and m+n−1 when both dimensions exceed 1. A checkerboard interior with a special first row and column realizes m+n−2; the one-dimensional cases require separate treatment.')
add(2014,3,6,'Number theory','Modular counting|Translation orbits|Quadratic forms',r'For an odd prime $p$, count the ordered tuples $(a_1,\ldots,a_p)$ with $0\le a_i<p$ such that $p\nmid a_1+\cdots+a_p$ but $p\mid a_1a_2+a_2a_3+\cdots+a_pa_1$.','Simultaneously translating every entry preserves the nonzero linear sum but makes the quadratic sum run through all residues. Partitioning into translation orbits shows exactly one in each p tuples is counted.',r'''Work modulo $p$, with cyclic indices. There are $(p-1)p^{p-1}$ tuples whose sum $S=\sum a_i$ is nonzero: choose the first $p-1$ entries arbitrarily, then exclude one value for the last.

Partition these tuples into orbits under simultaneous translation
$$(a_1,\ldots,a_p)\longmapsto(a_1+t,\ldots,a_p+t),\qquad t\in\mathbb F_p.$$
Every orbit has exactly $p$ distinct tuples. The sum remains $S$ because $pt=0$ modulo $p$. If $Q=\sum a_i a_{i+1}$, translation changes it to
$$Q+2tS+pt^2=Q+2tS\pmod p.$$
Since $p$ is odd and $S\ne0$, exactly one value of $t$ makes this zero. Consequently precisely one tuple per orbit is good, and the answer is
$$\boxed{(p-1)p^{p-2}}.$$''','The official solution accidentally interchanges the names of its linear and quadratic sums near the end. The original exposition corrects that algebra explicitly.')
add(2014,4,6,'Geometry','Radical axes|Power of a point|Directed angles|Cyclic quadrilaterals',r'A cyclic quadrilateral $ABCD$ contains an interior point $P$ such that $\angle PAB=\angle PBC=\angle PCD=\angle PDA$. Let $Q=AD\cap BC$ and $R=AB\cap CD$, assumed to be finite intersections. Prove that lines $PQ,PR$ make the same angle as the diagonals $AC,BD$.','Two uses of power of a point identify radical-axis intersections. The equal angles place these intersections on the two diagonals, and one last cyclic quadrilateral transfers the angle at their intersection to the angle at P.',r'''Write the common angle as $\alpha$, and use directed angles modulo $180^\circ$. Let $M$ be the second intersection of line $QP$ with circle $(PAD)$. Power of $Q$ gives
$$QM\cdot QP=QA\cdot QD=QB\cdot QC,$$
with directed products, so $M$ also lies on circle $(PBC)$. Hence
$$\angle PMA=\angle PDA=\alpha=\angle PBC=\angle PMC.$$
Thus $A,M,C$ are collinear.

Similarly, let $N$ be the second intersection of line $RP$ with circle $(PAB)$. Power of $R$ shows that $N$ also lies on $(PCD)$. Then
$$\angle PNB=\angle PAB=\alpha=\angle PCD=\angle PND,$$
so $B,N,D$ are collinear.

Put $X=AC\cap BD$. The preceding angle identities give $\angle PMX=\angle PNX$, and therefore $P,M,X,N$ are concyclic. It follows that the angle between $PQ=PM$ and $PR=PN$ equals the angle between $XM=AC$ and $XN=BD$, as required.''','The printed solution has inconsistent names R/S and switches the roles of the two diagonals and several angles. The original proof here reconstructs the intended argument with M on AC and N on BD.')
ids={x['id'] for x in new};data=json.loads((p/'data/americas.json').read_text());data=[x for x in data if x['id'] not in ids]+new
(p/'data/americas.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
c=json.loads((p/'research/americas-coverage.json').read_text())
for y,rates in {2010:[7,4.5,5,7,6.5],2011:[4,5.5,5.5,3.5,6.5],2012:[3,6,5.5,6.5,7],2013:[4,5,5,6.5,7],2014:[4.5,5,6,6,8]}.items():
 c['fullyScreened']=[x for x in c['fullyScreened'] if not(x['competition']=='CMO' and x['year']==y)]
 c['fullyScreened'].append(dict(competition='CMO',year=y,ratings={str(i+1):r for i,r in enumerate(rates)},source=f'https://cms.math.ca/wp-content/uploads/2019/07/sol{y}.pdf',exclusionNotes={2010:{},2011:{'4':'A standard pigeonhole argument on 2012 suffix residues, followed by cancelling a power of 10.'},2012:{'1':'Apply (t−2)²≥0 to x,y,z with weights 1,x,xy; the middle terms telescope.'},2013:{},2014:{'5':'Above target: a residue-dependent adversarial interval strategy needs a multi-level finite-occurrence termination proof.'}}[y]))
c['papersScreened']=len(c['fullyScreened']);c['problemAppearancesScreened']=sum(len(x['ratings']) for x in c['fullyScreened']+c['partiallyScreened']);c['uniqueIncluded']=len(data)
c['gaps'].append('CMO 2010–2014 full papers now individually screened in addition to 2015–2026. CMO 1969–2009 remains pending; CJMO began in 2020 and all available 2020–2026 papers were previously screened.')
c['qualityNotes'].append('CMO 2014 Q1 B₀ typo, Q3 swapped linear/quadratic sum names, and Q4 inconsistent point names and angle/diagonal references corrected in independently reconstructed original proofs. CMO 2012 Q2 original exposition supplies the omitted check that p+1 divides the common interval LCM.')
(p/'research/americas-coverage.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n');print('Added',len(new),'Total',len(data))
